          "status": "pass"
        },
        {
          "kind": "code",
          "file": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs",
          "line": 239,
          "rev": "head",
          "quote": "this.reportDiagnostic = reportAnalyzerDiagnostic is null ? null : diagnostic => ReportIfLocatedInCompilation(reportAnalyzerDiagnostic, diagnostic);"
        }
      ]
    },
    {
      "req": "REQ-2283-F3",
      "verdict": "met",
      "confidence_basis": "The constructor wraps reportDiagnostic so every diagnostic passes through ReportIfLocatedInCompilation, which reports only when diagnostic.Location.IsInSource; metadata-declared types and members therefore produce no diagnostics in the consuming compilation, and the tests pass with no unexpected diagnostics.",
      "evidence": [
        {
          "kind": "requirement",
          "req": "REQ-2283-F3",
          "quote": "Diagnostics about members of a type declared in a referenced assembly must not be reported at locations outside the compilation being analyzed."
        },
        {
          "kind": "code",
